from lecture_common import S,E,Q,L

def lessons():
 return [
 L(20,4,'웹과 HTTP·웹 서비스의 이해','1. 웹과 HTTP의 이해 · 2. 웹 서비스의 이해',[
 S(4,'웹의 시작과 하이퍼텍스트','PPT는 1989년 CERN의 팀 버너스리가 문서를 서로 연결하는 웹을 제안한 배경을 설명합니다. 하이퍼텍스트는 링크를 통해 문서 사이를 이동하는 구조이며 HTML은 문서의 구조와 연결을 표현합니다.','PPT의 HTML을 스크립트로 부르는 표현은 정정이 필요합니다. HTML은 마크업 언어이고 JavaScript처럼 동작을 실행하는 언어와 역할이 다릅니다.'),
 S([5,6],'HTTP Request와 메서드','HTTP는 클라이언트가 요청하고 서버가 응답하는 방식으로 자원을 주고받습니다. 요청에서 메서드·대상·프로토콜, 헤더, 필요할 때 본문을 구분합니다.','GET은 자원 조회의 의미를 가지며 URL의 쿼리 문자열에 값을 넣는 예가 나옵니다. POST는 요청 본문으로 값을 전달하는 대표 예입니다. HEAD는 GET과 같은 응답 메타정보를 요청하되 본문을 받지 않는 방식, OPTIONS는 지원 기능, PUT·DELETE는 자원 변경·삭제, TRACE는 진단 관련 메서드로 소개됩니다. 메서드 지원 여부와 서버 권한 검사는 별도로 필요합니다.'),
 S(7,'HTTP Response와 상태 코드','PPT의 응답 구조는 프로토콜 버전, 상태 코드와 설명, Content-Type 같은 형식·길이 관련 헤더, 실제 HTML·이미지 등의 본문으로 구성됩니다. 상태 줄은 HTTP/1.x의 표현 예이며 데이터가 항상 같은 형식의 텍스트 줄로 전송된다는 뜻은 아닙니다.','성공·이동·오류의 대분류를 읽은 뒤 개별 코드와 본문·로그를 확인합니다. 4xx는 단순히 클라이언트 소프트웨어가 고장 났다는 뜻이 아니라 요청을 이행할 수 없는 여러 조건을 포함합니다.',table=(['범위','의미'],[['1xx','정보 제공·중간 응답'],['2xx','요청의 성공적 처리'],['3xx','리다이렉션 등 추가 동작'],['4xx','요청·권한 등 클라이언트 요청 관련 오류'],['5xx','서버가 요청을 이행하지 못한 오류'] ])),
 S(8,'GET·POST의 값과 HTTPS','GET의 쿼리와 POST의 본문은 값의 위치가 다를 뿐 어느 방식 자체도 암호화를 제공하지 않습니다. POST로 보냈다는 이유만으로 비밀번호가 안전하게 보호된다고 판단하면 안 됩니다.','HTTPS는 전송 경로를 보호합니다. URL은 브라우저 이력·서버 로그·공유 경로에 남을 수 있으므로 민감한 값을 쿼리에 넣지 않는 방향으로 설계합니다. 서버 내부 저장·권한·출력 취약점은 HTTPS와 별개의 통제입니다.'),
 S([9,10],'프런트엔드: HTML·CSS·JavaScript','PPT는 브라우저가 해석하는 정적 페이지와 동적 동작을 비교합니다. HTML은 구조, CSS는 모양, JavaScript는 브라우저에서의 동작을 담당합니다. 정적이라는 이유만으로 모든 보안 문제가 없는 것은 아닙니다.','브라우저는 화면의 값과 요청을 사용자가 바꿀 수 있는 환경입니다. 화면의 입력 제한과 숨김 필드는 사용 편의 기능이며 서버가 신뢰할 수 있는 권한 근거가 아닙니다.'),
 S(11,'백엔드와 REST API','Java·.NET·Python·Ruby·JavaScript 같은 서버 환경은 요청 경로와 입력을 받아 업무 처리·DB 접근을 수행하고 HTML이나 JSON 등으로 응답합니다. REST API도 클라이언트가 호출하는 서버 인터페이스입니다.','화면을 통하지 않고 요청을 직접 보낼 수 있으므로 인증·인가·입력 검증은 각 서버 처리에서 필요합니다. 프런트엔드에서 값이 올바르게 보이는지와 서버가 그 값을 믿어도 되는지는 다른 문제입니다.')
 ],[Q('HTML·CSS·JavaScript의 역할은?','구조·표현·동작을 각각 담당한다.','HTML은 마크업 언어이며 실행 스크립트와 구분합니다.'),Q('POST로 보내면 값이 암호화되나?','아니다. 전송 보호에는 HTTPS 등 별도 통제가 필요하다.','값이 본문에 있다는 사실과 암호화는 다릅니다.'),Q('HTTP 상태 코드의 다섯 대분류는?','정보·성공·리다이렉션·클라이언트 요청 관련 오류·서버 오류다.','코드의 범위와 실제 응답 내용을 함께 읽습니다.')],[E('연결 종료·캐시·HTTP 버전 보충','PPT의 매 응답 뒤 연결을 끊는 설명은 초기 HTTP의 단순화한 흐름입니다. HTTP/1.1은 지속 연결을 기본으로 하며 HTTP/2·3도 하나의 응답이 끝났다고 항상 연결을 종료하지 않습니다. HTML을 스크립트로 부르는 표현과 응답의 상태 줄도 버전·역할에 따라 구분합니다.',links=[('HTTP 의미 규격 RFC 9110','https://www.rfc-editor.org/rfc/rfc9110.html'),('HTTP/1.1 RFC 9112','https://www.rfc-editor.org/rfc/rfc9112.html')])]),
 L(21,4,'웹 해킹: 프록시와 정보 수집','3. 웹 해킹 · 4. 웹의 취약점과 보안 개요',[
 S([12,13,14,15,16],'스캐너와 Burp Suite 프록시의 위치','자동 스캐너는 많은 항목을 빠르게 점검하지만 오탐·누락이 있어 실제 요청·응답과 서비스 조건을 확인해야 합니다. 도구의 경고가 곧 취약점 재현이나 피해 성공을 뜻하지 않습니다.','Burp Suite 프록시의 PPT 구성은 브라우저 → 로컬 프록시 → 대상 서버입니다. 127.0.0.1은 자기 컴퓨터의 루프백 주소, 8080은 예시 프록시 포트입니다. 브라우저의 프록시 설정과 Burp 리스너의 주소·포트가 맞아야 요청을 관찰할 수 있습니다.','PPT의 화면은 특정 버전의 위치·기본값입니다. 프록시를 지나는 요청/응답을 인터셉트하는 개념과 설정 역할을 익히며, 제품 업데이트 후 메뉴 모양까지 항상 같다고 가정하지 않습니다.'),
 S([17,18,19,20,21],'응답 변조와 브라우저에 보이는 값','PPT는 게시판 응답을 중간에 잡아 표시 값을 1에서 2로 바꾼 뒤 브라우저에 전달하는 예를 단계별로 보여 줍니다. 서버가 보낸 응답과 사용자가 받은 화면이 달라지는 위치가 프록시입니다.','이 변화는 해당 브라우저가 받은 내용의 변화입니다. 응답 글자를 고쳤다는 이유만으로 서버 DB의 원본까지 바뀌었다고 결론내리면 안 됩니다. 서버 상태 변경 여부는 이후 요청과 서버 처리를 따로 확인합니다.'),
 S([22,23],'왕복하는 값을 서버가 다시 믿는 문제','서버가 보낸 값 20을 클라이언트가 40으로 바꾸고, 다음 요청에서 되돌려 보낸 40을 서버가 그대로 사용한다면 문제가 생깁니다. 공격의 핵심은 화면을 고쳤다는 사실보다 서버가 클라이언트 값을 권위 있는 값으로 재사용한 지점입니다.','가격·잔액·역할 같은 중요한 값은 서버의 신뢰 가능한 원본과 업무 규칙으로 다시 계산·검증합니다. 숨긴 입력 필드나 이전 응답에 있었다는 이유만으로 값을 신뢰하지 않습니다.'),
 S([24,25],'요청 매개변수와 객체 권한','PPT의 문서 번호를 2에서 1로 바꾸는 요청 예는 사용자가 객체 ID를 직접 조작할 수 있음을 보여 줍니다. 번호가 문법상 정상이어도 그 자료를 읽을 권한이 있다는 뜻은 아닙니다.','서버는 로그인 여부와 해당 문서에 대한 소유·공유·역할 권한을 요청마다 확인해야 합니다. 접근 버튼을 숨기는 것은 서버의 객체 권한 검사를 대체하지 못합니다.'),
 S([26,27,28],'검색 엔진을 이용한 노출 정보 확인','PPT의 site:는 검색할 도메인 범위, filetype:은 파일 형식, intitle:은 제목 조건을 제한하는 예입니다. 검색 결과에 백업 파일·설정·내부 문서가 노출되는지 확인하는 관점입니다.','학습용으로 site:example.test filetype:pdf처럼 자신이 관리하거나 허가받은 범위를 가정해 읽습니다. 검색 결과가 없다고 정보가 비공개라는 보장은 없고, 검색됐다는 사실만으로 모든 파일 내용과 권한을 확인한 것도 아닙니다.'),
 S(29,'robots.txt의 역할과 한계','User-agent는 수집 프로그램, Disallow는 수집하지 말아 달라는 경로 지침입니다. PPT는 Googlebot 또는 *와 /dbconn.ini·/admin 같은 경로를 예로 듭니다.','robots.txt는 공개적으로 읽을 수 있는 수집 지침이며 서버 접근 제어가 아닙니다. 민감한 경로를 적는 것만으로 파일·관리 화면이 보호되지 않으므로 실제 인증·권한과 배포 정책을 적용해야 합니다.'),
 S(30,'OWASP 취약점 분류의 도입','PPT는 OWASP 2025 기준의 일부 범주로 A01 접근 제어 실패, A02 보안 설정 오류, A04 암호화 실패, A05 인젝션, A07 인증 실패 등을 연결합니다. XSS는 입력이 실행 코드로 해석되는 인젝션의 맥락에서 다룹니다.','이 슬라이드는 뒤의 취약점을 분류하는 개요이며 Top 10 전체 목록을 모두 싣는 표는 아닙니다. 범주 번호는 판에 따라 달라질 수 있으므로 2025라는 기준을 함께 기억합니다.')
 ],[Q('응답의 숫자를 고치면 서버 DB도 자동으로 바뀌나?','아니다. 브라우저에 전달되는 응답 변조와 서버 상태 변경은 다르다.','다음 요청과 서버의 신뢰 여부를 확인합니다.'),Q('site:·filetype:·intitle:은 무엇을 제한하나?','도메인 범위·파일 형식·문서 제목이다.','검색 조건과 서버의 접근 권한은 별개입니다.'),Q('robots.txt의 Disallow는 접근 차단인가?','아니다. 수집 프로그램에 대한 지침이다.','민감한 경로에는 실제 서버 권한 검사가 필요합니다.')]),
 L(22,4,'인젝션과 SQL 삽입','4. 웹의 취약점과 보안 · 인젝션',[
 S(31,'인젝션의 공통 원리','SQL·운영체제 명령·LDAP 등에서 외부 입력을 명령 구조와 섞으면 데이터가 문법으로 해석될 수 있습니다. 입력을 어디에 결합하고 어느 해석기가 실행하는지 확인하는 것이 인젝션 분석의 출발점입니다.','PPT의 로그인 SQL은 이메일과 비밀번호를 조건에 넣어 사용자를 조회합니다. 문자열 연결 방식에서는 따옴표·연산자 같은 입력이 원래 의도한 WHERE 조건의 구조를 바꿀 수 있습니다.'),
 S([32,33],'정상 로그인과 문자열 결합 코드 읽기','정상 이메일·비밀번호가 모두 맞으면 결과 행이 있고, 비밀번호가 다르면 결과가 없는 예로 시작합니다. 입력 변수 user_email·password가 SQL 문자열로 들어가고 db.each의 콜백에서 결과 행 유무에 따라 성공 또는 Login_Failed로 처리되는 흐름을 읽습니다.','PPT 코드에는 공백·등호 표기 등 그대로 실행하기 어려운 부분이 있습니다. 아래는 해당 제어 흐름을 문장으로 옮긴 재구성 의사코드이며 원본 실행 코드와 구분합니다.',code='[PPT 코드 흐름을 글로 재구성]\n입력 이메일·비밀번호 수신\n→ 문자열을 결합하여 SELECT 구성\n→ DB 조회와 행 콜백 처리\n→ 결과 행 있음: 로그인 처리 / 없음: Login_Failed'),
 S([34,35],'항상 참인 조건과 적용 지점','입력의 따옴표가 문자열 경계를 닫고 OR 조건 등이 SQL 문법으로 해석되면 원래의 사용자·비밀번호 검사 조건을 바꿀 수 있습니다. 같은 입력도 쿼리 형태·연산자 우선순위·주석·자료형에 따라 결과가 다릅니다.','로그인뿐 아니라 검색·게시글·우편번호 조회 등 외부 입력을 SQL로 사용하는 다른 기능도 같은 원리를 점검합니다. 로그인 화면에 특정 문자열을 막았다는 사실만으로 전체 인젝션을 막았다고 판단하지 않습니다.'),
 S(36,'매개변수화와 서버 검증','매개변수화한 쿼리는 SQL 구조를 고정하고 값만 별도로 바인딩합니다. 값에 따옴표·OR 같은 문자열이 들어 있어도 SQL 문법으로 연결하지 않는 것이 목적입니다.','입력의 형식·범위도 서버에서 확인합니다. 테이블명·정렬 열처럼 값 매개변수로 바인딩할 수 없는 구조 요소는 허용 목록으로 선택하고, 단순한 위험 문자 삭제만으로 모든 쿼리를 보호하려 하지 않습니다.')
 ],[Q('SQL 삽입에서 입력이 넘어서는 경계는?','데이터 값과 실행할 SQL 문법의 경계다.','입력이 명령 구조로 해석되는 결합 지점을 찾습니다.'),Q('로그인 외의 검색 기능도 점검해야 하는 이유는?','어느 기능이든 외부 입력을 SQL에 결합하면 같은 원리의 문제가 생길 수 있기 때문이다.','화면별 필터보다 서버의 처리 방식이 중요합니다.'),Q('매개변수화의 핵심은?','SQL 구조를 고정하고 입력을 값으로 별도 전달하는 것이다.','검증·최소 권한·객체 권한은 여전히 필요합니다.')],[E('직접 만든 코드 예제의 범위','아래 Python/SQLite 예제와 계산은 PPT의 Node.js 코드를 그대로 옮긴 것이 아닙니다. 문자열 결합과 값 바인딩의 차이를 메모리 내부 가상 테이블에서 확인하는 별도 학습 예제입니다. 결과 2와 0은 해당 테이블·자료형·입력 조건에만 해당합니다.')]),
 L(23,4,'인증·XSS·접근 제어·설정·민감정보','4. 웹의 취약점과 보안 · 주요 취약점',[
 S([37,38],'인증 실패와 객체 접근 제어','admin/admin 같은 기본 자격정보를 방치하면 알려진 값으로 관리자 접근이 가능할 수 있습니다. 기본 계정·비밀번호 변경과 사용자 인증을 관리해야 합니다.','정상 세션을 가진 사용자라도 UserNo·문서 ID를 바꿔 타인의 정보를 읽을 수 있다면 객체 권한 검사 문제입니다. 로그인 인증과 각 기능·대상의 인가를 서버에서 분리해 확인합니다.'),
 S([39,40,41,42],'저장형 XSS의 단계와 피해','공격 형태의 입력이 게시물 등에 저장되고, 다른 사용자가 볼 때 안전하게 데이터로 출력되지 않아 브라우저에서 스크립트로 실행되는 과정이 저장형 XSS입니다. 작성자 입력 → 저장 → 다른 사용자 조회 → 출력 문맥에서 실행의 순서로 읽습니다.','PPT의 alert 예제는 스크립트가 실행됐음을 눈으로 확인하는 시연입니다. 후속 예는 location과 document.cookie 같은 값을 이용한 이동·정보 전송 가능성을 설명합니다. 경고창 성공이 모든 쿠키를 읽거나 모든 권한을 얻었다는 증거는 아닙니다.','쿠키 접근·가짜 화면·사용자 권한으로 요청하기 등 피해는 브라우저 정책과 애플리케이션 조건에 따라 다릅니다. 입력이 텍스트여야 할 위치에서 실행 코드가 되는 지점을 찾는 것이 핵심입니다.'),
 S([43,44,45],'접근 제어와 경로 탐색','권한 검사는 공통 서버 로직에서 요청마다 수행하고 기본적으로 거절하는 구조로 설계합니다. URL을 아는 것, 화면 링크가 보이는 것, 로그인한 것은 각각 자원 권한과 다릅니다.','PPT는 .과 ..의 경로 의미, /board/upload에서 ../list.jsp·관리자 화면·download.jsp 등으로 이동하는 경로 조작을 보여 줍니다. /etc/passwd 같은 의도하지 않은 파일까지 읽게 되는지 여부는 서버의 경로 처리와 파일 권한에 달려 있습니다.','서버는 사용자 파일명을 그대로 결합하지 않고 허용된 파일 ID·저장 위치를 관리하며 정규화 후에도 허용 디렉터리 안인지 확인해야 합니다. 확장자나 화면 제한만으로 경로 경계를 보장하지 않습니다.'),
 S([46,47],'디렉터리 목록·백업·주석·업로드','디렉터리 목록은 경로의 파일 이름과 구조를 노출할 수 있습니다. login.asp.bak 같은 백업·임시 파일이 코드로 처리되지 않고 내려받아지면 소스·설정·자격정보가 유출될 수 있습니다.','주석도 브라우저로 전달되는 HTML·JavaScript에 들어 있으면 보일 수 있습니다. 서버 내부에서만 처리되고 전달되지 않는 주석까지 무조건 공개된다는 뜻은 아닙니다.','업로드 파일이 서버에서 실행되면 웹셸 등 명령 실행으로 이어질 수 있습니다. 확장자뿐 아니라 실제 형식·크기·저장·실행·제공 정책을 관리합니다. 모든 웹 침해에 반드시 업로드가 필요하다는 뜻은 아닙니다.'),
 S([48,49],'리버스 텔넷과 역방향 연결','PPT의 리버스 텔넷·netcat 관련 그림은 외부에서 서버로 새 연결을 여는 방식과 서버가 외부로 먼저 연결하는 방식을 비교합니다. 웹셸 등으로 명령 실행이 가능한 조건에서 내부 서버의 발신 통신이 경로가 될 수 있습니다.','리스너는 연결을 기다리는 쪽이고 접속 주체는 연결을 시작하는 쪽입니다. 들어오는 통신만 제한하면 발신 경로의 악용을 놓칠 수 있어 외부 연결 정책·실행 권한·업로드 저장소의 실행 금지와 함께 확인합니다. 공격 도구를 실행하지 않고 연결의 방향과 전제 조건을 설명합니다.'),
 S(50,'민감정보 노출과 공격 탐지·대응','신용카드·주민등록번호·인증정보처럼 민감한 값은 필요한 범위만 수집·저장하고 접근 권한, 전송·저장 보호와 키 관리를 함께 적용합니다. 암호화 키가 같은 경로로 노출되거나 로그에 평문이 남는 문제도 확인합니다.','PPT의 불충분한 공격 방어(Insufficient Attack Protection)는 애플리케이션의 탐지·로그·반응 부족을 설명하는 역사적 분류입니다. 공격 신호를 기록하고 반복·비정상 접근에 대응하는 기능이 필요하며, 이 이름을 모든 최신 OWASP 판의 동일 번호 항목으로 취급하지 않습니다.')
 ],[Q('저장형 XSS의 실행 시점은?','저장된 입력을 다른 사용자의 브라우저에 안전하지 않게 출력할 때다.','저장과 출력·실행의 단계를 나눕니다.'),Q('경로 탐색에서 ..를 이용해 넘으려는 경계는?','서버가 허용한 파일·디렉터리 범위다.','정규화한 최종 경로와 파일 권한을 확인합니다.'),Q('역방향 연결은 어느 쪽이 접속을 시작하나?','내부의 서버 등이 외부로 연결을 시작한다.','수신 차단과 발신 정책을 함께 이해합니다.')],[E('XSS와 쿠키 속성의 관계','HttpOnly는 스크립트의 쿠키 읽기를 제한하지만 XSS 실행 자체를 없애지는 않습니다. 스크립트가 같은 출처에서 요청을 보내거나 화면을 바꾸는 피해도 있으므로 출력 문맥에 맞는 인코딩·안전한 DOM API·검증된 HTML 정화와 CSP 같은 방어를 조합합니다. 아래 사례의 쿠키·주소·사용자는 직접 만든 가상 자료입니다.')]),
 L(24,4,'CSRF·구성요소·API와 보안 대책','4. 웹의 취약점과 보안 · CSRF와 종합 대책',[
 S(51,'CSRF의 성립 조건','CSRF는 로그인된 브라우저가 쿠키 등 인증정보를 자동으로 첨부하는 조건을 악용해 사용자가 원하지 않은 상태 변경 요청을 보내게 하는 공격입니다. 공격자가 응답 내용을 읽지 못하더라도 송금·설정 변경 같은 처리가 일어날 수 있습니다.','공격 대상 서버가 악성 스크립트를 실행한다는 정의와는 다릅니다. 어떤 사이트의 콘텐츠를 본 브라우저가 어느 서버로 어떤 인증 상태의 요청을 보내는지 그려 봅니다.'),
 S(52,'PPT의 자동 제출 폼과 구성요소·API 위험','PPT는 무료 혜택을 가장한 페이지가 uid=wishfree, mode=pay_for_order, amount=10000 같은 숨김 값을 담고 자동으로 10,000원 결제 POST를 보내는 예를 보여 줍니다. 화면의 문구와 실제 제출 대상·값이 다르다는 점, 기존 로그인 상태가 요청에 사용될 수 있다는 점을 읽습니다.','원본 예제의 submin·hiddne 등 오탈자와 깨진 따옴표는 그대로 실행할 코드가 아닙니다. 폼 자동 제출의 의도와 서버의 요청 검증 조건을 설명하는 자료로 구분합니다.','알려진 취약점이 있는 라이브러리·구성요소는 실제 버전·노출·사용 조건을 확인해 수정하고 검증합니다. API도 화면과 동일하게 인증·객체 권한·입력·요청 제한을 적용해야 합니다. UI를 통하지 않는다는 이유로 검사를 생략하지 않습니다.'),
 S(53,'XSS와 CSRF의 차이와 요청 검증','XSS는 신뢰하지 않는 데이터가 브라우저의 실행 코드로 바뀌는 문제, CSRF는 브라우저의 인증 상태를 이용한 원치 않는 요청의 문제입니다. 둘을 모두 쿠키 탈취라고 정의하면 동작을 놓칩니다.','서버의 CSRF 토큰 확인, 요청 출처 확인, SameSite 등 요청 조건에 맞는 방어를 적용합니다. POST 사용이나 HTTPS만으로 CSRF가 사라지지 않으며 XSS가 있으면 같은 출처의 요청 수행에도 영향을 줄 수 있습니다.'),
 S(54,'출력 문맥에 맞춘 XSS 방어','HTML 본문·속성·스크립트·URL 등 어디에 출력되는지에 따라 안전한 처리가 달라집니다. 텍스트용 안전한 출력 기능을 쓰고, HTML을 허용해야 한다면 허용된 구조만 남기는 정화가 필요합니다.','단순히 <와 >를 지우는 방식만으로 모든 문맥을 보호하지 않습니다. 입력과 출력의 역할을 구분하고, 브라우저에서 코드가 되는 경계를 차단합니다.'),
 S(55,'입력·인증·권한·세션의 종합 대책','서버에서 입력의 자료형·길이·범위를 검증하고 SQL은 매개변수화합니다. 인증과 인가는 모든 페이지·API의 실제 처리 지점에 일관되게 적용합니다.','세션의 생성·권한 변경·만료·로그아웃 무효화를 관리하고, 기본 계정·불필요한 파일·기능을 정리합니다. 취약점 이름과 방어 기술을 일대일로 외우기보다 어느 경계를 어떤 검사로 보호하는지 설명합니다.')
 ],[Q('CSRF에서 공격자가 응답을 읽어야만 상태 변경이 가능한가?','아니다. 인증정보가 첨부된 요청을 서버가 받아 처리하는 조건이 핵심이다.','전송된 요청과 응답의 읽기 권한은 다릅니다.'),Q('XSS와 CSRF는 각각 무엇의 문제인가?','브라우저 코드 실행 경계와 인증된 요청의 정당성 검증 문제다.','쿠키 탈취라는 한 결과로 두 공격을 정의하지 않습니다.'),Q('전체 웹 보안 대책의 서버 측 공통 요소는?','입력 검증·매개변수화·요청별 인증과 권한·세션 수명 관리다.','모든 화면·API에 일관되게 적용해야 합니다.')])
 ]
